import{_ as a,o as r,c as d,a2 as o}from"./chunks/framework.DpXDHk3d.js";const u=JSON.parse('{"title":"6.1 导线的种类与型号","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/06-chapter-6-dao-xian-dian-lan-yu-di-ya-xian-lu/6-1-dao-xian-de-zhong-lei-yu-xing-hao.md","filePath":"electrician/low-voltage-electrician/06-chapter-6-dao-xian-dian-lan-yu-di-ya-xian-lu/6-1-dao-xian-de-zhong-lei-yu-xing-hao.md","lastUpdated":1793095197000}'),e={name:"electrician/low-voltage-electrician/06-chapter-6-dao-xian-dian-lan-yu-di-ya-xian-lu/6-1-dao-xian-de-zhong-lei-yu-xing-hao.md"};function n(l,t,i,s,h,g){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="_6-1-导线的种类与型号" tabindex="-1">6.1 导线的种类与型号 <a class="header-anchor" href="#_6-1-导线的种类与型号" aria-label="Permalink to &quot;6.1 导线的种类与型号&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>电线是电流的&quot;路&quot;。这一节认识最常见的导线:哪些是<strong>裸导线</strong>,哪些是<strong>绝缘导线</strong>,以及最关键的能力——<strong>看懂型号</strong>。看到 BV、BLV、BVR 能立刻说出是什么线,是电工的基本功。</p><h2 id="一、导线的种类" tabindex="-1">一、导线的种类 <a class="header-anchor" href="#一、导线的种类" aria-label="Permalink to &quot;一、导线的种类&quot;">​</a></h2><h3 id="_1-裸导线" tabindex="-1">1. 裸导线 <a class="header-anchor" href="#_1-裸导线" aria-label="Permalink to &quot;1. 裸导线&quot;">​</a></h3><p>没有绝缘层的导线,用于<strong>架空线路</strong>、母线等绝缘距离有保证的场合。</p><table tabindex="0"><thead><tr><th>名称</th><th>型号</th><th>特点</th></tr></thead><tbody><tr><td>铜绞线</td><td>TJ</td><td>导电好,贵</td></tr><tr><td>铝绞线</td><td>LJ</td><td>轻、便宜,用于架空线路</td></tr><tr><td>钢芯铝绞线</td><td><strong>LGJ</strong></td><td>铝线包裹钢芯,强度高,用于高压架空线</td></tr></tbody></table><h3 id="_2-绝缘导线" tabindex="-1">2. 绝缘导线 <a class="header-anchor" href="#_2-绝缘导线" aria-label="Permalink to &quot;2. 绝缘导线&quot;">​</a></h3><p>导线外面有绝缘层,用于低压配电线路、设备内部接线。</p><ul><li><strong>塑料绝缘线</strong>:用聚氯乙烯(PVC)绝缘,最常用;</li><li><strong>橡皮绝缘线</strong>:用橡皮绝缘,柔软耐磨;</li><li>按芯线又分<strong>单股(硬线)和多股(软线)</strong>。</li></ul><h2 id="二、型号字母含义-必背" tabindex="-1">二、型号字母含义(必背) <a class="header-anchor" href="#二、型号字母含义-必背" aria-label="Permalink to &quot;二、型号字母含义(必背)&quot;">​</a></h2><p>看懂型号,先记字母:</p><table tabindex="0"><thead><tr><th>字母</th><th>含义</th></tr></thead><tbody><tr><td><strong>B</strong></td><td>布线用(绝缘导线)</td></tr><tr><td><strong>V</strong></td><td>聚氯乙烯绝缘(塑料)</td></tr><tr><td><strong>L</strong></td><td>铝(芯);没有 L 表示铜芯</td></tr><tr><td><strong>R</strong></td><td>软线(多股细丝)</td></tr><tr><td><strong>X</strong></td><td>橡皮绝缘</td></tr><tr><td><strong>Y</strong></td><td>聚乙烯绝缘</td></tr></tbody></table><h3 id="常见导线型号举例" tabindex="-1">常见导线型号举例 <a class="header-anchor" href="#常见导线型号举例" aria-label="Permalink to &quot;常见导线型号举例&quot;">​</a></h3><table tabindex="0"><thead><tr><th>型号</th><th>含义</th></tr></thead><tbody><tr><td><strong>BV</strong></td><td>铜芯聚氯乙烯绝缘导线(最常见的&quot;硬线&quot;)</td></tr><tr><td><strong>BLV</strong></td><td><strong>铝</strong>芯聚氯乙烯绝缘导线</td></tr><tr><td><strong>BVR</strong></td><td>铜芯聚氯乙烯绝缘<strong>软线</strong></td></tr><tr><td><strong>BVV</strong></td><td>铜芯聚氯乙烯绝缘<strong>聚氯乙烯护套</strong>线(两芯带护套)</td></tr><tr><td><strong>BX</strong></td><td>铜芯橡皮绝缘导线</td></tr><tr><td><strong>BLX</strong></td><td>铝芯橡皮绝缘导线</td></tr></tbody></table><blockquote><p>💡 解读技巧:<strong>先认材料、再认芯线</strong>。如 BLV = B(布线)+L(铝)+V(聚氯乙烯绝缘)= 铝芯塑料绝缘线;没有 L 的就是铜芯(BV = 铜芯塑料线)。</p></blockquote><blockquote><p>⚠️ 高频考点:<strong>BV 是铜芯,BLV 是铝芯</strong>——判断导线芯线材质,就看有没有 L。</p></blockquote><h2 id="三、铜芯-vs-铝芯怎么选" tabindex="-1">三、铜芯 vs 铝芯怎么选 <a class="header-anchor" href="#三、铜芯-vs-铝芯怎么选" aria-label="Permalink to &quot;三、铜芯 vs 铝芯怎么选&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>铜芯</th><th>铝芯</th></tr></thead><tbody><tr><td>导电性</td><td>好</td><td>较差</td></tr><tr><td>抗腐蚀</td><td>好</td><td>差(接头易氧化发热)</td></tr><tr><td>价格</td><td>贵</td><td>便宜</td></tr><tr><td>重量</td><td>重</td><td>轻</td></tr><tr><td>用途</td><td>低压配电、设备接线首选</td><td>架空线路、部分低压线路</td></tr></tbody></table><blockquote><p>💡 现在低压线路普遍<strong>优先用铜芯</strong>;铝芯多用于架空线路。铝线接头氧化是安全隐患(接触电阻变大发热),要特别注意。</p></blockquote><h2 id="四、考点提示" tabindex="-1">四、考点提示 <a class="header-anchor" href="#四、考点提示" aria-label="Permalink to &quot;四、考点提示&quot;">​</a></h2><ul><li>✅ 型号字母:B=布线、V=聚氯乙烯、L=铝芯、R=软、X=橡皮。</li><li>✅ <strong>BV=铜芯塑料线,BLV=铝芯塑料线</strong>。</li><li>✅ 有 L 是铝芯,没 L 是铜芯。</li><li>⚠️ 易混点:BV 与 BLV 只差一个 L,材质完全不同。</li></ul><h2 id="五、本节小结" tabindex="-1">五、本节小结 <a class="header-anchor" href="#五、本节小结" aria-label="Permalink to &quot;五、本节小结&quot;">​</a></h2><ul><li>导线分裸导线(架空用)和绝缘导线(低压配电用)。</li><li>型号看字母:先辨材料(V=塑料、X=橡皮),再看芯线(L=铝、无L=铜)。</li><li>铜芯导电好、铝芯便宜,低压线路多用铜芯。</li></ul><h2 id="六、自测练习" tabindex="-1">六、自测练习 <a class="header-anchor" href="#六、自测练习" aria-label="Permalink to &quot;六、自测练习&quot;">​</a></h2><ol><li>(单选)型号 BV 导线表示()。 A. 铝芯塑料绝缘线　B. 铜芯塑料绝缘线　C. 铜芯橡皮绝缘线　D. 铝芯橡皮绝缘线</li><li>(单选)BLV 导线中的字母 L 表示()。 A. 铝芯　B. 铜芯　C. 塑料绝缘　D. 软线</li><li>(判断)BVR 是铜芯聚氯乙烯绝缘软线。( )</li><li>(单选)用于高压架空线路,强度较高的导线是()。 A. BV　B. BLX　C. 钢芯铝绞线　D. BVV</li><li>(判断)低压配电线路一般优先选用铜芯导线。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>B</strong>。BV = 铜芯聚氯乙烯(塑料)绝缘导线。</li><li><strong>A</strong>。L 表示铝芯,没有 L 是铜芯。</li><li><strong>√</strong>。R 表示软线。</li><li><strong>C</strong>。钢芯铝绞线(LGJ)用于高压架空线路。</li><li><strong>√</strong>。铜芯导电性好,低压线路多用。</li></ol></details>',27)])])}const b=a(e,[["render",n]]);export{u as __pageData,b as default};
